zonaCargada('f','75_-2',{"h:muralla-punica":{"epoca":"Tartessos, fenicios y griegos","resumen":"Un tramo de la muralla de Qart Hadasht, la ciudad que fundó Asdrúbal hacia el 227 a. C. como capital cartaginesa en Hispania. Un centro de interpretación explica las Guerras Púnicas y la conquista de la ciudad por Escipión en el 209 a.","ver_alli":["El centro de interpretación se levanta sobre el tramo de muralla hallado en 1987: se camina junto a los dos muros paralelos y las estancias entre ellos.","Un audiovisual explica las Guerras Púnicas y la conquista de la ciudad por Escipión en el 209 a. C.","Completar la visita en el ARQVA, Museo Nacional de Arqueología Subacuática, con el barco fenicio Mazarrón 1."],"fuentes":["https://www.civitatis.com/es/cartagena/entrada-centro-interpretacion-muralla-punica/","https://www.google.com/maps/place/?q=place_id:ChIJHd_plIhBYw0RUWidlvGm-Pw","https://www.openstreetmap.org/?mlat=37.6041&mlon=-0.9786#map=18/37.6041/-0.9786"]},"h:cartagena-romana":{"epoca":"Romano","resumen":"La antigua Qart Hadasht fue una gran ciudad romana. Su teatro, de época de Augusto, se descubrió en 1988 bajo casas y una catedral, y hoy se llega a él a través del museo de Rafael Moneo.","ver_alli":["Al teatro se entra por el Museo del Teatro Romano, el edificio de Rafael Moneo en la plaza del Ayuntamiento.","En el recorrido, fijarse en los restos del barrio bizantino levantado sobre el teatro abandonado.","En el cerro del Molinete, el Museo Foro Romano Molinete muestra el foro, las termas y un templo.","Cerca están la Casa de la Fortuna, el Augusteum, la Muralla púnica y el ARQVA."],"fuentes":["https://www.turismoregiondemurcia.es/en/museum/museo-del-teatro-romano-141","https://puertodeculturas.cartagena.es/horarios_tarifas.asp","https://www.google.com/maps/place/?q=place_id:ChIJ75yEEylCYw0RCgIafZ_3Hvo","https://www.openstreetmap.org/?mlat=37.5998&mlon=-0.9839#map=18/37.5998/-0.9839"]},"h:murallas-y-arsenal-de-cartagena":{"epoca":"Ilustración y Neoclásico","resumen":"En 1731 Felipe V aprobó el proyecto de un gran arsenal en Cartagena, cabeza del departamento marítimo del Mediterráneo y una de las tres grandes bases navales de España, con Ferrol y Cádiz.","ver_alli":["Pasear junto a la Muralla del Mar, el tramo que se conserva entero frente al puerto.","Ver desde la calle Real la Puerta del Arsenal y su torre del reloj.","El Museo Naval está a unos 300 m de la Puerta del Arsenal.","Los lienzos que rodean el arsenal hacia el castillo de Galeras conservan sus almenas originales."],"fuentes":["https://es.wikipedia.org/wiki/Arsenal_de_Cartagena","https://es.wikipedia.org/wiki/Murallas_de_Carlos_III","https://en.wikipedia.org/wiki/Cartagena_Naval_Base","https://murciatoday.com/the-naval-arsenal-in-cartagena_1100409-a.html","https://www.google.com/maps/place/?q=place_id:ChIJVRCuwy5CYw0RLu-G6O6KsVQ","https://www.openstreetmap.org/?mlat=37.6003&mlon=-0.9886#map=18/37.6003/-0.9886"]},"h:museo-refugio-de-la-guerra-civil-de-cart":{"epoca":"Guerra Civil","resumen":"Cartagena, base de la escuadra republicana, fue una de las ciudades más castigadas por la aviación durante la Guerra Civil. El peor ataque fue el del 25 de noviembre de 1936, el «bombardeo de las cuatro horas», atribuido a la Legión Cóndor, con bombas de 250 kilos sobre el Arsenal y la estación seguidas de cientos de bombas incendiarias.","ver_alli":["Recorrer las galerías excavadas en la roca del monte de la Concepción.","Escuchar los testimonios grabados de quienes vivieron los bombardeos.","La entrada está en la calle Gisbert, junto al ascensor panorámico."],"fuentes":["https://murciatoday.com/the-civil-war-air-raid-shelter-museum-in-cartagena_3021-a.html","https://es.hispanopedia.com/wiki/Museo-Refugio_de_la_Guerra_Civil","https://www.google.com/maps/place/?q=place_id:ChIJawOJoIdBYw0RZ50Exeb7Btw","https://www.openstreetmap.org/?mlat=37.6001&mlon=-0.9809#map=18/37.6001/-0.9809"]},"h:muralla-bizantina-de-cartagena":{"epoca":"Bizantino","resumen":"Restos de la muralla de Carthago Spartaria, la capital de la provincia bizantina de Spania. En 589 el gobernador Comenciolo dejó una lápida que lo recuerda, hoy en el Museo Arqueológico de Cartagena.","ver_alli":["Hay un tramo visible en el recorrido del Museo del Teatro Romano."]},"n:parque-regional-de-calblanque-monte-de-las-cenizas-y-pena-del-aguila--murcia":{"municipio":"Cartagena","resumen":"Parque natural en Cartagena (Murcia), con 2.784 ha. Franja litoral virgen entre Cartagena y La Manga, con dunas, saladares y calas de arena dorada poco frecuentes en el entorno muy urbanizado del Mar Menor; incluye antiguas labores mineras de la Sierra Minera de Cartagena-La Unión en su extremo oriental.","web":"https://www.carm.es/web/pagina?IDCONTENIDO=1198&IDTIPO=100"},"n:parque-regional-de-las-salinas-y-arenales-de-san-pedro-del-pinatar--murcia":{"municipio":"San Pedro del Pinatar","resumen":"Ruta circular de 17,6 km en San Pedro del Pinatar (Murcia). Es casi llano, entre -1 y 3 m de altitud. Se calcula en 4 h de marcha y su dificultad es fácil (2 sobre 5).","web":"https://www.spain.info/en/nature/salinas-arenales-san-pedro-pinatar-regional-park/"},"n:marina-del-carmoli--murcia":{"municipio":"Los Urrutias (Cartagena)","resumen":"Humedal en Los Urrutias (Cartagena) (Murcia). Humedal costero del litoral del Mar Menor, saladar y zona de marisma en proceso de expropiación y recuperación por la Comunidad Autónoma dentro del plan de protección del Mar Menor, con presencia de limícolas y anátidas invernantes."},"n:saladar-de-lo-poyo--murcia":{"municipio":"Los Nietos (Cartagena)","resumen":"Humedal en Los Nietos (Cartagena) (Murcia). Saladar costero en la orilla sur del Mar Menor, integrado en el Paisaje Protegido del Mar Menor, hábitat de limícolas y de la tortuga mora en algunas zonas próximas; sendero perimetral de tierra sin asfaltar."},"n:mirador-de-las-mestizas--murcia":{"municipio":"Cartagena","resumen":"Mirador en Cartagena (Murcia). Mirador dentro del Parque Regional de Calblanque, Monte de las Cenizas y Peña del Águila con vistas sobre las playas vírgenes del parque y el Mediterráneo; dato de coordenadas aproximado, pendiente de verificación exacta sobre el terreno."},"n:parque-regional-de-calblanque--murcia":{"municipio":"Cartagena","resumen":"Parque natural en Cartagena (Murcia). Playas fosiles dunas y salinas protegidas junto al mar Menor."},"r:vv-de-torrevieja--alicante":{"municipio":"Torrevieja","resumen":"Vía verde lineal de 6,6 km en Torrevieja (Alicante). Acumula unos 5 m de subida, entre -1 y 7 m de altitud. Se calcula en 1 h 30 min de marcha. Atraviesa en parte el Parque Natural de las Lagunas de la Mata y Torrevieja.","web":"https://www.viasverdes.com/itinerarios/itinerario.asp?id=15","distancia_km":6.61,"desnivel_positivo_m":5,"tiempo_estimado_horas":1.5,"altitud_max_m":7,"esf":0,"fo":["l",6.2,"",6.6]},"r:pr-mu-001-centro-de-interpretacion-de-cobaticas-cento-de-interpretacion-de-cobat--murcia":{"municipio":"Cartagena","resumen":"Sendero de pequeño recorrido (PR) circular de 8,5 km en Cartagena (Murcia). Sale y vuelve a Centro de Interpretacion de Cobaticas. Cartagena. Acumula 175 m de subida, entre 6 y 141 m de altitud. Se calcula en 2 h 40 min de marcha. Valoración MIDE: medio 2, itinerario 2, desplazamiento 3 y esfuerzo 3 (de 1 a 5).","web":"http://misendafedme.es/buscador-de-senderos/etapa/pr-mu-1-vuelta-al-cabezo-de-la-fuente","distancia_km":8.51,"desnivel_positivo_m":175,"tiempo_estimado_horas":2.67,"altitud_max_m":141,"esf":1,"fo":["c",0.0,"",8.4]},"r:pr-mu-002-monte-de-las-cenizas-collado-de-atamaria--murcia":{"municipio":"Cartagena","resumen":"Sendero de pequeño recorrido (PR) lineal de 2,7 km en Cartagena (Murcia). Va de Collado de Atamaría, en la carretera de Portman. Cartagena a Batería defensiva de Las Cenizas. Acumula 166 m de subida y 35 m de bajada, entre 144 y 303 m de altitud. Se calcula en 1 h 40 min de marcha.","web":"http://misendafedme.es/buscador-de-senderos/etapa/pr-mu-2-monte-de-las-cenizas","distancia_km":2.74,"desnivel_positivo_m":166,"tiempo_estimado_horas":1.65,"altitud_max_m":303,"esf":0,"fo":["l",1.7,"",2.7]},"r:pr-mu-003-portman-llano-del-beal--murcia":{"municipio":"Cartagena","resumen":"Sendero de pequeño recorrido (PR) lineal de 6,4 km en Cartagena (Murcia). Acumula unos 129 m de subida y 208 m de bajada, entre 29 y 235 m de altitud. Se calcula en 1 h 45 min de marcha.","web":"http://misendafedme.es/buscador-de-senderos/etapa/pr-mu-3-llano-del-beal","distancia_km":6.38,"desnivel_positivo_m":129,"tiempo_estimado_horas":1.75,"altitud_max_m":235,"esf":0,"fo":["l",4.0,"",6.3]},"r:pr-mu-004-barrio-de-la-concepcion-cartagena-barrio-de-la-concepcion-cartagena--murcia":{"municipio":"Cartagena","resumen":"Sendero de pequeño recorrido (PR) circular de 5,7 km en Cartagena (Murcia). Sale y vuelve a Barrio de la Concepción (Cartagena). Acumula 428 m de subida, entre 24 y 255 m de altitud. Se calcula en 1 h 50 min de marcha. Valoración MIDE: medio 2, itinerario 2, desplazamiento 2 y esfuerzo 2 (de 1 a 5).","web":"http://misendafedme.es/buscador-de-senderos/etapa/pr-mu-4-vuelta-a-la-atalaya","distancia_km":5.65,"desnivel_positivo_m":428,"tiempo_estimado_horas":1.87,"altitud_max_m":255,"esf":1,"fo":["c",0.0,"",5.6]},"r:vv-barrio-del-peral--murcia":{"municipio":"Cartagena","resumen":"Vía verde lineal de 2 km en Cartagena (Murcia). Es casi llano, entre 12 y 38 m de altitud. Se calcula en 25 minutos de marcha.","web":"https://www.viasverdes.com/itinerarios/itinerario.asp?id=129","distancia_km":1.96,"tiempo_estimado_horas":0.4166666666666667,"altitud_max_m":38,"esf":0,"fo":["l",1.8,"",2.0]},"t:torre-de-cabo-roig-orihuela":{"municipio":"Orihuela","resumen":"Torre vigía del siglo XVI en la costa de Orihuela, construida para vigilar la llegada de piratas berberiscos. Es cilíndrica, de mampostería, con la base en talud y la puerta en alto sobre el talud. Por dentro, una bóveda de ladrillo separa la planta baja de la primera. Es bien de interés cultural.","ver_alli":["Base ataluzada","Puerta elevada con sillares","Vista sobre el cabo"],"visita":"exterior libre","fuentes":["https://es.wikipedia.org/wiki/Torre_de_Cabo_Roig","https://www.wikidata.org/wiki/Q6150353"]},"t:torre-de-la-horadada-pilar-de-la-horadada":{"municipio":"Pilar de la Horadada","resumen":"Torre vigía costera levantada en 1591 dentro del sistema defensivo de Felipe II para avisar de los desembarcos piratas en el antiguo Campo de la Horadada. Está en la punta rocosa del núcleo costero de Torre de la Horadada, que toma de ella su nombre. Es Bien de Interés Cultural y hoy es el símbolo del litoral del municipio.","ver_alli":["La torre sobre la punta, junto al puerto deportivo","Vistas sobre la costa sur hacia el Mar Menor"],"visita":"exterior libre","fuentes":["https://es.wikipedia.org/wiki/Pilar_de_la_Horadada","https://www.comunitatvalenciana.com/es/alacant-alicante/pilar-de-la-horadada/monumentos/torre-horadada","https://es.wikipedia.org/wiki/Torre_Horadada","http://www.wikidata.org/entity/Q43146215"]},"t:canteras-romanas-de-mil-palmeras-pilar-de-la-horadada":{"municipio":"Pilar de la Horadada","resumen":"Antigua cantera romana excavada en la roca a la orilla del mar, entre la playa de Mil Palmeras y la del Río Seco. De ella se sacaba piedra en época romana; las guías oficiales la sitúan en los siglos I-II a. C. y la relacionan con obras como la Vía Augusta. Se ven todavía en la roca los cortes rectos de los bloques extraídos.","ver_alli":["Los cortes escalonados de los bloques en la roca","Su posición a pie de playa"],"visita":"acceso libre","fuentes":["https://es.wikipedia.org/wiki/Pilar_de_la_Horadada","https://www.comunitatvalenciana.com/es/alacant-alicante/pilar-de-la-horadada","https://nominatim.openstreetmap.org/"]},"t:museo-arqueologico-y-etnologico-gratiniano-baches-pilar-de-la-horadada":{"municipio":"Pilar de la Horadada","resumen":"Es el museo principal del municipio y reúne los hallazgos arqueológicos y objetos que cuentan la historia del Pilar de la Horadada. Combina una parte de arqueología, con restos del poblamiento antiguo de la zona por la que pasaba la Vía Augusta, y otra etnológica sobre la vida tradicional del campo.","ver_alli":["Piezas arqueológicas del término municipal","Sección etnológica de oficios y vida rural"],"visita":"horario o cita previa (consultar con el ayuntamiento)","fuentes":["https://es.wikipedia.org/wiki/Pilar_de_la_Horadada","https://es.wikipedia.org/wiki/Museo_Arqueológico_y_Etnológico_Gratiniano_Baches"]},"t:iglesia-de-nuestra-senora-del-pilar-pilar-de-la-horadada":{"municipio":"Pilar de la Horadada","resumen":"Iglesia parroquial del centro del pueblo, construida en 1981 en el solar de un templo anterior que se derribó. Su torre campanario, de estilo neomudéjar, es la imagen más reconocible del municipio. Guarda varias tallas del escultor local José María Sánchez Lozano.","ver_alli":["Torre campanario neomudéjar","Imágenes de José María Sánchez Lozano"],"visita":"horario de culto","fuentes":["https://es.wikipedia.org/wiki/Pilar_de_la_Horadada","https://www.comunitatvalenciana.com/es/alacant-alicante/pilar-de-la-horadada/monumentos/iglesia-parroquial-nuestra-senora-del-pilar","https://es.wikipedia.org/wiki/Iglesia_de_Nuestra_Se%C3%B1ora_del_Pilar_(Pilar_de_la_Horadada)","http://www.wikidata.org/entity/Q25413971"]},"t:eras-de-la-sal-torrevieja":{"municipio":"Torrevieja","resumen":"Conjunto de arquitectura industrial del siglo XVIII que funcionó como depósito y embarcadero de la sal desde 1777 hasta 1958, en la antigua cala Cornuda. Desde aquí se cargaban los barcos con la sal de las lagunas. En uno de sus patios se celebra cada verano el Certamen Internacional de Habaneras.","ver_alli":["Muros y patios del antiguo depósito de sal","Restos del embarcadero junto al mar"],"visita":"exterior libre","fuentes":["https://es.wikipedia.org/wiki/Torrevieja","https://es.wikipedia.org/wiki/Era_de_la_Sal_(Torrevieja)","http://www.wikidata.org/entity/Q95567644"]},"t:casino-de-torrevieja-torrevieja":{"municipio":"Torrevieja","resumen":"Sede de la sociedad cultural Casino, levantada en 1896 por el arquitecto José Guardiola Picó. Es uno de los edificios más vistosos del centro, de estilo modernista con aire oriental. Se considera uno de los emblemas de la ciudad.","ver_alli":["Fachada modernista","Salones interiores decorados"],"visita":"desconocido","fuentes":["https://es.wikipedia.org/wiki/Torrevieja","https://es.wikipedia.org/wiki/Casino_de_Torrevieja","http://www.wikidata.org/entity/Q52556191"]},"t:submarino-delfin-s-61-torrevieja":{"municipio":"Torrevieja","resumen":"Submarino de la Armada española que estuvo en servicio de 1973 a 2003 y hoy está conservado a flote en el puerto como museo. Forma parte de los museos flotantes del Museo del Mar y de la Sal, junto al patrullero de Aduanas Albatros III. Se puede recorrer por dentro.","ver_alli":["Interior del submarino","Patrullero Albatros III atracado al lado"],"visita":"horario de visita (entrada)","fuentes":["https://es.wikipedia.org/wiki/Museo_del_Mar_y_de_la_Sal","https://es.wikipedia.org/wiki/Delfín_(S-61)"]},"t:museo-del-mar-y-de-la-sal-torrevieja":{"municipio":"Torrevieja","resumen":"Museo etnológico inaugurado en 1995 y dedicado a la vida marinera y salinera de Torrevieja. Tiene secciones de arqueología submarina, salinas, pesca artesanal, cabotaje, velería, carpintería de ribera y artesanía de la sal. Expone desde piezas halladas en el litoral hasta herramientas de las salinas.","ver_alli":["Sección de las salinas","Maquetas de barcos y carpintería de ribera"],"visita":"horario de museo","fuentes":["https://es.wikipedia.org/wiki/Museo_del_Mar_y_de_la_Sal","http://www.wikidata.org/entity/Q6034460"]},"t:iglesia-arciprestal-de-la-inmaculada-concepcion-torrevieja":{"municipio":"Torrevieja","resumen":"Iglesia principal de Torrevieja, erigida en 1789 y reconstruida en 1844 tras el terremoto de 1829. En la reconstrucción se aprovecharon las piedras de la vieja torre que daba nombre al pueblo. Es de estilo neoclásico y guarda diversas obras de arte.","ver_alli":["Fachada neoclásica sobre la plaza de la Constitución"],"visita":"horario de culto","fuentes":["https://es.wikipedia.org/wiki/Torrevieja","http://www.wikidata.org/entity/Q117763954"]},"t:pailebote-pascual-flores-torrevieja":{"municipio":"Torrevieja","posicion_nota":"Ubicación sin confirmar: está en el pueblo de Torrevieja; el punto no marca el sitio exacto.","lat_pueblo":37.9778,"lon_pueblo":-0.6833,"resumen":"Goleta de tipo pailebote construida en Torrevieja en 1917, como las que usaban los marineros del pueblo para comerciar con la sal. Hoy se conserva reconstruida en el puerto como parte de los museos flotantes.","ver_alli":["Arboladura del velero en el puerto"],"visita":"desconocido","fuentes":["https://turismo.torrevieja.es/en/poi/pailebote-pascual-flores","https://es.wikipedia.org/wiki/Museo_del_Mar_y_de_la_Sal"]},"t:museo-de-la-semana-santa-tomas-valcarcel-torrevieja":{"municipio":"Torrevieja","resumen":"Museo que guarda todo el año, salvo en Semana Santa, el patrimonio de las procesiones de Torrevieja. Se exponen imágenes, tronos, estandartes, esculturas y pinturas de las cofradías.","ver_alli":["Tronos e imágenes procesionales"],"visita":"desconocido","fuentes":["https://es.wikipedia.org/wiki/Torrevieja","https://nominatim.openstreetmap.org/"]},"t:iglesia-de-nuestra-senora-del-rosario-de-la-mata-torrevieja":{"municipio":"Torrevieja","posicion_nota":"Ubicación sin confirmar: está en el pueblo de Torrevieja; el punto no marca el sitio exacto.","lat_pueblo":37.9778,"lon_pueblo":-0.6833,"resumen":"Iglesia de la pedanía de La Mata, construida en 1896.","visita":"horario de culto","fuentes":["https://es.wikipedia.org/wiki/Torrevieja"]},"t:molineta-de-lo-ferris-torrevieja":{"municipio":"Torrevieja","resumen":"Pequeño molino de viento en la zona de Lo Ferrís, catalogado en el inventario de patrimonio de la Generalitat.","visita":"exterior libre","fuentes":["http://www.wikidata.org/entity/Q66361238"]},"t:iglesia-de-san-miguel-arcangel-san-miguel-de-salinas":{"municipio":"San Miguel de Salinas","resumen":"Iglesia parroquial en la plaza de la Libertad. El templo se terminó en 1719 y en 1723 se convirtió en parroquia propia, separada de la iglesia del Salvador de Orihuela. Sufrió con el terremoto de 1829 y en la Guerra Civil perdió buena parte de su estructura original.","ver_alli":["Plaza de la Libertad"],"visita":"horario de culto","fuentes":["https://es.wikipedia.org/wiki/San_Miguel_de_Salinas","https://www.tuscasasrurales.com/que-ver-en-san-miguel-de-salinas-357.htm","http://www.wikidata.org/entity/Q62062555"]},"t:molino-del-marques-san-miguel-de-salinas":{"municipio":"San Miguel de Salinas","resumen":"Molino de viento de piedra, de cuerpo cilíndrico, en un alto junto al casco urbano. Es Bien de Relevancia Local. Por su posición es también un buen mirador sobre el Campo de Salinas.","ver_alli":["Torre cilíndrica de piedra","Vistas sobre el pueblo y el campo"],"visita":"exterior libre","fuentes":["https://www.comunitatvalenciana.com/es/alacant-alicante/san-miguel-de-salinas","http://www.wikidata.org/entity/Q77579236"]},"t:casa-lo-meca-san-miguel-de-salinas":{"municipio":"San Miguel de Salinas","posicion_nota":"Ubicación sin confirmar: está en el pueblo de San Miguel de Salinas; el punto no marca el sitio exacto.","lat_pueblo":37.9806,"lon_pueblo":-0.7897,"resumen":"Casa de labor del siglo XVIII, típica de las grandes fincas del Campo de Salinas. Se organiza en torno a un patio central y permite distinguir la zona del propietario de la de los trabajadores.","ver_alli":["Patio central"],"visita":"desconocido","fuentes":["https://www.tuscasasrurales.com/que-ver-en-san-miguel-de-salinas-357.htm","https://es.wikipedia.org/wiki/San_Miguel_de_Salinas"]},"t:torre-de-zahurdas-san-miguel-de-salinas":{"municipio":"San Miguel de Salinas","resumen":"Torre defensiva catalogada por la Generalitat en el paraje de Las Zahurdas, donde también hay restos arqueológicos.","visita":"desconocido","fuentes":["https://www.tuscasasrurales.com/que-ver-en-san-miguel-de-salinas-357.htm","http://www.wikidata.org/entity/Q97361581"]},"t:torre-ciega-cartagena":{"municipio":"Cartagena","resumen":"Monumento funerario romano del siglo I a. C. que formaba parte de una gran necrópolis junto a la vía de entrada a Carthago Nova. Es una de las tres torres funerarias romanas mejor conservadas de la península, con la de los Escipiones (Tarragona) y la de Hércules (Villajoyosa). Su inscripción, hoy ilegible, la dedicaba a Tito Didio.","ver_alli":["Revestimiento de opus reticulatum con piedrecitas piramidales de andesita","Esquinas reforzadas con sillares de caliza"],"visita":"exterior libre","fuentes":["https://es.wikipedia.org/wiki/Torre_Ciega","https://www.wikidata.org/wiki/Q6150087"]},"t:palacio-de-aguirre-muram-cartagena":{"municipio":"Cartagena","resumen":"Palacete modernista de Víctor Beltrí construido en 1898-1901 para el empresario minero Camilo Aguirre. Es sede del Museo Regional de Arte Moderno (MURAM) y conserva varias estancias originales.","ver_alli":["Cúpula de cerámica y ángeles cerámicos en la fachada","Salón de baile con techo de Cecilio Pla (Alegoría de la primavera)","Escalera imperial y oratorio neogótico"],"visita":"MURAM martes a sábado 11-14 y 17-20 h, domingo 11-14 h; gratuito; tel. 968 50 16 07","fuentes":["https://es.wikipedia.org/wiki/Palacio_de_Aguirre","https://turismo.cartagena.es/cartagena_gratis.asp?idioma=2","https://www.wikidata.org/wiki/Q6057842"]},"t:gran-hotel-de-cartagena-cartagena":{"municipio":"Cartagena","resumen":"Edificio modernista inaugurado en 1916, iniciado por Tomás Rico y terminado por Víctor Beltrí para el empresario Celestino Martínez Vidal. Fue de los mejores hoteles de España en su época y alojó al espía alemán Wilhelm Canaris en la Primera Guerra Mundial. Se salvó del derribo en 1976 y es BIC desde 2012.","ver_alli":["Veleta con la fecha de 1910","Fachada modernista con cúpula en la esquina"],"visita":"exterior libre","fuentes":["https://es.wikipedia.org/wiki/Gran_Hotel_de_Cartagena","https://www.wikidata.org/wiki/Q5884350"],"rp":["r:gr-250-tramo-de-region-de-murcia-6-etapas--murcia"]},"t:casa-llagostera-cartagena":{"municipio":"Cartagena","resumen":"Fachada modernista de 1913-1916 en la calle Mayor, obra de Víctor Beltrí para la familia catalana de comerciantes Llagostera, considerada «la más original y hermosa de la arquitectura murciana del siglo XX». Está totalmente revestida de cerámica de Gaspar Polo. El interior se demolió en 2010 y solo queda la fachada.","ver_alli":["Cerámicas de Minerva y Mercurio","Escudos de Cartagena, Murcia, Barcelona y Manlleu"],"visita":"exterior libre","fuentes":["https://es.wikipedia.org/wiki/Casa_Llagostera","https://www.wikidata.org/wiki/Q5754304"],"rp":["r:gr-250-tramo-de-region-de-murcia-6-etapas--murcia"]},"t:iglesia-de-santa-maria-de-gracia-cartagena":{"municipio":"Cartagena","resumen":"Gran templo del casco antiguo comenzado en 1713 con el apoyo del cardenal Belluga, centro de las procesiones de Semana Santa. Fue dañado en la revolución cantonal (1873) y en 1936, y restaurado en estilo neobarroco en 1943. Preside el altar la imagen medieval de la Virgen del Rosell, flanqueada por los Cuatro Santos de Cartagena de Francisco Salzillo, que antes estaban en la catedral vieja.","ver_alli":["Cuatro Santos de Cartagena de Salzillo (s. XVIII)","Virgen del Rosell, antigua patrona","Capillas de las cofradías"],"visita":"horario de culto","fuentes":["https://es.wikipedia.org/wiki/Iglesia_de_Santa_Mar%C3%ADa_de_Gracia_(Cartagena)","https://www.wikidata.org/wiki/Q5911788"],"rp":["r:gr-250-tramo-de-region-de-murcia-6-etapas--murcia"]},"t:basilica-de-la-caridad-cartagena":{"municipio":"Cartagena","resumen":"Templo neoclásico de planta circular y estructura metálica, inspirado en el Panteón de Roma, diseñado por el ingeniero naval Tomás de Tallerie. Es sede de la patrona, la Virgen de la Caridad, imagen napolitana del siglo XVIII, y guarda obras de Salzillo y su escuela de la iglesia anterior.","ver_alli":["Cúpula sobre planta circular","Cristo crucificado de Salzillo y conjunto rococó de la Virgen de las Ánimas","Lienzos de Manuel Ussel de Guimbarda (1893)"],"visita":"horario de culto","fuentes":["https://es.wikipedia.org/wiki/Bas%C3%ADlica_de_la_Caridad_(Cartagena)","https://www.wikidata.org/wiki/Q5722065"]},"t:fuerte-de-navidad-cartagena":{"municipio":"Cartagena","resumen":"Batería de costa de estilo neoclásico en la boca del puerto, construida entre el siglo XVII y 1860,, que cruzaba sus fuegos con las de Santa Ana y Trincabotijas; tenía casamatas para ocho cañones abajo y otros ocho a barbeta arriba. Hoy es el Centro de Interpretación de la Arquitectura Defensiva, junto al faro de Navidad.","ver_alli":["Casamatas con cañones","Explicación de la vida de los artilleros","Terraza con vistas a la bahía y la ciudad"],"visita":"temporada 15 mar-10 dic (cerrado 11 dic-14 mar), horario variable; 4 €, o 10 € con barco turístico; puertodeculturas.cartagena.es","fuentes":["https://es.wikipedia.org/wiki/Fuerte_de_Navidad_(Cartagena)","https://www.turismoregiondemurcia.es/en/monument/fuerte-de-navidad---centro-de-interpretacion-de-la-arquitectura-defensiva-194","https://www.wikidata.org/wiki/Q21968145"]},"t:monasterio-de-san-gines-de-la-jara-cartagena":{"municipio":"Cartagena","resumen":"Antiguo monasterio franciscano en la falda del cabezo de San Ginés, cerca del Mar Menor, de posible origen mozárabe; en el siglo XIII ya había una ermita con torre defensiva. Conserva la fachada renacentista con los escudos de los franciscanos y los Vélez y una iglesia del siglo XVII con retablo de perspectiva fingida. Tras décadas de ruina (BIC desde 1992), está en restauración desde 2012.","ver_alli":["Fachada renacentista con escudos","Retablo pintado en perspectiva fingida","Torre y restos del claustro"],"visita":"exterior libre; interior en restauración","fuentes":["https://es.wikipedia.org/wiki/Monasterio_de_San_Gin%C3%A9s_de_la_Jara","https://www.wikidata.org/wiki/Q4407365"]},"t:ermitas-del-monte-miral-cartagena":{"municipio":"Cartagena","resumen":"Restos de un eremitorio en el monte Miral o cabezo de San Ginés, junto al monasterio, donde según la tradición vivieron ascetas desde época visigoda. Hubo nueve ermitas dedicadas a santos ermitaños; quedan seis, de mampostería con hiladas de ladrillo, tres de ellas BIC. La más conocida es la de los Ángeles, junto a la cueva donde habría vivido San Ginés.","ver_alli":["Ermita de los Ángeles","Ruinas escalonadas por la ladera","Vistas al Mar Menor desde las ventanas"],"visita":"acceso libre (ruinas en el monte)","fuentes":["https://es.wikipedia.org/wiki/Ermitas_del_monte_Miral","https://www.wikidata.org/wiki/Q5836679"]},"t:faro-de-cabo-de-palos-cartagena":{"municipio":"Cartagena","resumen":"Faro sobre el promontorio más alto de Cabo de Palos, donde en la Antigüedad hubo un templo a Baal Hammon y en 1578 se acabó una torre vigía contra los berberiscos. El faro actual de sillería entró en servicio en 1865 y fue declarado BIC en 2025.","ver_alli":["Torre de sillería sobre el promontorio","Vistas a las islas Hormigas y La Manga"],"visita":"exterior libre","fuentes":["https://es.wikipedia.org/wiki/Faro_de_Cabo_de_Palos","https://www.wikidata.org/wiki/Q5856380"]},"t:museo-regional-del-bolillo-la-palma-cartagena":{"municipio":"Cartagena","resumen":"Pequeño museo en La Palma dedicado al encaje de bolillos, tradición artesana del Campo de Cartagena.","ver_alli":["Piezas de encaje de bolillos"],"visita":"lunes y jueves 11-13 h, cerrado julio y agosto; gratuito; tel. 968 55 40 45 (confirmar)","fuentes":["https://turismo.cartagena.es/cartagena_gratis.asp?idioma=2","https://www.wikidata.org/wiki/Q125904847","https://nominatim.openstreetmap.org"]},"t:teatro-circo-apolo-el-algar-cartagena":{"municipio":"Cartagena","resumen":"Teatro modernista a la italiana, con platea y palcos, proyectado por Pedro Cerdán en 1905 e inaugurado en 1907 en pleno auge minero de la sierra. Es BIC desde 1998 y se restauró hasta 2009, incluido su telón de boca pintado a mano.","ver_alli":["Fachada modernista","Sala a la italiana con palcos","Telón de boca pintado a mano"],"visita":"en funciones o actos; exterior libre","fuentes":["https://es.wikipedia.org/wiki/Teatro_Apolo_(El_Algar)","https://www.wikidata.org/wiki/Q5494132"]},"t:museo-etnografico-de-los-puertos-de-santa-barbara-cartagena":{"municipio":"Cartagena","posicion_nota":"Ubicación sin confirmar: está en el pueblo de Cartagena; el punto no marca el sitio exacto.","lat_pueblo":37.6019,"lon_pueblo":-0.9842,"resumen":"Museo etnográfico gratuito en la pedanía de Los Puertos de Santa Bárbara, dedicado a la vida rural tradicional del oeste del Campo de Cartagena.","ver_alli":["Objetos de la vida rural"],"visita":"martes 17:30-20:30 y sábado 10:30-13:30, o con cita (tel. 968 16 30 24 / 630 73 40 58); gratuito","fuentes":["https://turismo.cartagena.es/cartagena_gratis.asp?idioma=2"]},"t:ermita-de-la-virgen-del-pasico-torre-pacheco":{"municipio":"Torre-Pacheco","resumen":"Pequeña ermita rústica en el paraje de El Pasico; según la tradición oral su origen se remonta al siglo XVIII (los documentos se perdieron en la Guerra Civil). Su curiosidad es la imagen venerada: una Dolorosa que se ve dibujada en las vetas de una piedra de alabastro, hallada según la leyenda en un almendro. Es punto de partida de la Ruta de los Molinos.","ver_alli":["Piedra de alabastro con la silueta de la Dolorosa","Claveles que dejan los devotos como ofrenda","Molino del Pasico a pocos metros"],"visita":"exterior libre","fuentes":["https://www.turismoregiondemurcia.es/catalogos/OTTPACHECO34052581Guia Turistica.pdf","https://itrem.carm.es/en/monument/ermita-de-el-pasico--6229/","https://nominatim.openstreetmap.org"]},"t:molino-del-pasico-torre-pacheco":{"municipio":"Torre-Pacheco","resumen":"Molino harinero de viento de 1844, del tipo mediterráneo del Campo de Cartagena, con velas latinas y techo giratorio. Fue restaurado por el Ayuntamiento y se visita con guía, que explica el funcionamiento en sus tres plantas. Es el escenario de la tradicional Merienda de El Pasico el lunes de Pascua.","ver_alli":["Velas latinas triangulares y caperuza giratoria","Maquinaria de molienda en las tres plantas","Ermita del Pasico al lado"],"visita":"visita guiada; consultar Oficina de Turismo de Torre-Pacheco (tel. 968 57 99 37)","fuentes":["https://www.turismoregiondemurcia.es/catalogos/OTTPACHECO34052581Guia Turistica.pdf","https://nominatim.openstreetmap.org","https://es.wikipedia.org/wiki/Torre-Pacheco"]},"t:antiguo-ayuntamiento-de-torre-pacheco-torre-pacheco":{"municipio":"Torre-Pacheco","resumen":"Edificio clasicista de 1866 con fachada y cúpula, obra de Francisco José Belmonte, que también sirvió de cárcel y de escuela y se restauró en 2001. Hoy alberga la Oficina de Turismo, el antiguo salón de plenos y la exposición permanente «El Cabezo Gordo: la montaña neandertal», dedicada al yacimiento de la Sima de las Palomas.","ver_alli":["Escudo de Torre-Pacheco labrado en piedra","Antiguo salón de plenos","Exposición sobre los neandertales del Cabezo Gordo"],"visita":"horario de la Oficina de Turismo (tel. 968 57 99 37, turismo@torrepacheco.es)","fuentes":["https://www.turismoregiondemurcia.es/catalogos/OTTPACHECO34052581Guia Turistica.pdf","https://nominatim.openstreetmap.org"]},"t:iglesia-de-nuestra-senora-del-rosario-torre-pacheco-torre-pacheco":{"municipio":"Torre-Pacheco","resumen":"Templo parroquial de finales del siglo XX con planta piramidal, que conserva piezas de la iglesia antigua: lápida fundacional de 1603, lápida de la torre de 1704, escudo del deán y un arco renacentista-manierista atribuido a Pedro Milanés, todos declarados BIC. Junto a ella se levantó en 2005-2011 una torre campanario moderna con piedra del Cabezo Gordo y alabastro.","ver_alli":["Arco renacentista-manierista de la iglesia antigua","Retablo «La Creación» del jesuita Javier Zurbano","Virgen del Rosario de Sánchez Lozano y vidrieras"],"visita":"horario de culto","fuentes":["https://www.turismoregiondemurcia.es/catalogos/OTTPACHECO34052581Guia Turistica.pdf","https://nominatim.openstreetmap.org"]},"t:casa-fontes-torre-pacheco":{"municipio":"Torre-Pacheco","resumen":"Antigua casa nobiliaria del siglo XIX de los marqueses de Torre Pacheco, con su escudo en la fachada. Fue residencia de temporada y escenario de fiestas con gente del mundo artístico. Hoy es municipal y está rehabilitada como espacio cultural.","ver_alli":["Escudo de los marqueses en la fachada","Jardín y estancias rehabilitadas"],"visita":"desconocido","fuentes":["https://www.turismoregiondemurcia.es/catalogos/OTTPACHECO34052581Guia Turistica.pdf","https://nominatim.openstreetmap.org","https://es.wikipedia.org/wiki/Torre-Pacheco"]},"t:iglesia-de-nuestra-senora-de-los-dolores-y-capilla-del-calvario-dolores-de-pacheco-torre-pacheco":{"municipio":"Torre-Pacheco","posicion_nota":"Ubicación sin confirmar: está en el pueblo de Torre-Pacheco; el punto no marca el sitio exacto.","lat_pueblo":37.7431,"lon_pueblo":-0.9539,"resumen":"Iglesia barroca levantada entre 1720 y 1725, la llamada «Ermita Nueva», con retablo y camarín; la imagen de la Virgen es de José Sánchez Lozano (1940). A sus pies está la capilla-cripta de los Ayuso, panteón familiar de finales del siglo XVIII, del que la leyenda dice que un pasadizo lo unía con Roda.","ver_alli":["Retablo y camarín barrocos","Capilla-cripta de los Ayuso a los pies del templo"],"visita":"horario de culto","fuentes":["https://www.turismoregiondemurcia.es/catalogos/OTTPACHECO34052581Guia Turistica.pdf"]},"t:iglesia-de-nuestra-senora-de-la-consolacion-san-cayetano-torre-pacheco":{"municipio":"Torre-Pacheco","posicion_nota":"Ubicación sin confirmar: está en el pueblo de Torre-Pacheco; el punto no marca el sitio exacto.","lat_pueblo":37.7431,"lon_pueblo":-0.9539,"resumen":"Iglesia del primer tercio del siglo XIX levantada sobre una ermita de los siglos XV-XVI, en la pedanía de San Cayetano. Conserva un retablo de madera.","ver_alli":["Retablo de madera"],"visita":"horario de culto","fuentes":["https://www.turismoregiondemurcia.es/catalogos/OTTPACHECO34052581Guia Turistica.pdf"]},"t:castillo-de-ros-balsicas-torre-pacheco":{"municipio":"Torre-Pacheco","posicion_nota":"Ubicación sin confirmar: está en el pueblo de Torre-Pacheco; el punto no marca el sitio exacto.","lat_pueblo":37.7431,"lon_pueblo":-0.9539,"resumen":"Caserón con torreón almenado en Balsicas, mandado construir por la orden de San Felipe Neri y donado después al general Antonio Ros de Olano, que obtuvo título de vizconde. Junto a él está la iglesia del Rosario de Balsicas.","ver_alli":["Torreón almenado","Iglesia del Rosario de Balsicas al lado"],"visita":"propiedad privada; solo exterior","fuentes":["https://www.turismoregiondemurcia.es/catalogos/OTTPACHECO34052581Guia Turistica.pdf","https://es.wikipedia.org/wiki/Torre-Pacheco"]},"t:casa-pedreno-el-jimenado-torre-pacheco":{"municipio":"Torre-Pacheco","posicion_nota":"Ubicación sin confirmar: está en el pueblo de Torre-Pacheco; el punto no marca el sitio exacto.","lat_pueblo":37.7431,"lon_pueblo":-0.9539,"resumen":"Casa solariega en El Jimenado que la guía municipal fecha en el siglo XV, con escudo de armas y reloj de sol en la fachada. En su comedor principal se encontraron restos de pinturas murales antiguas.","ver_alli":["Escudo de armas","Reloj de sol"],"visita":"desconocido","fuentes":["https://www.turismoregiondemurcia.es/catalogos/OTTPACHECO34052581Guia Turistica.pdf"]},"t:museo-casa-del-labrador-roldan-torre-pacheco":{"municipio":"Torre-Pacheco","posicion_nota":"Ubicación sin confirmar: está en el pueblo de Torre-Pacheco; el punto no marca el sitio exacto.","lat_pueblo":37.7431,"lon_pueblo":-0.9539,"resumen":"Museo etnográfico de la vida rural del Campo de Cartagena creado en los años 80 por Luciano Martínez Ros en Roldán.","ver_alli":["Aperos y objetos de la vida campesina"],"visita":"desconocido","fuentes":["https://www.turismoregiondemurcia.es/catalogos/OTTPACHECO34052581Guia Turistica.pdf"]},"t:noria-de-sangre-de-torre-pacheco-torre-pacheco":{"municipio":"Torre-Pacheco","resumen":"Noria de tiro animal (de sangre) para sacar agua, protegida como bien de interés cultural.","visita":"exterior libre","fuentes":["https://www.wikidata.org/wiki/Q67915194"]},"t:casa-del-pinon-la-union":{"municipio":"La Unión","resumen":"Edificio modernista-ecléctico de 1899 del arquitecto Pedro Cerdán, encargado como viviendas de alquiler de lujo por Joaquín Peñalver, apodado «el Piñón» por su baja estatura. Rehabilitado en 2008, hoy es el Ayuntamiento de La Unión y acoge además el pequeño Museo del Cante de las Minas, sobre la historia minera y el flamenco local.","ver_alli":["Planta baja de piedra con ménsulas de cabezas de león","Balaustrada corrida y balcones de rejería","Museo del Cante de las Minas, con grabaciones de cantes del festival"],"visita":"exterior libre; museo lunes a sábado 10-13 h, 3 € (Oficina de Turismo 968 54 16 14; datos de 2014)","fuentes":["https://es.wikipedia.org/wiki/Casa_del_Pi%C3%B1%C3%B3n","https://m.murciatoday.com/museo-del-cante-de-las-minas-flamenco-museum-in-la-unión_24078-a.html","https://www.wikidata.org/wiki/Q2880408"]},"t:antiguo-mercado-publico-de-la-union-la-union":{"municipio":"La Unión","resumen":"Mercado de abastos modernista de 1907, obra de Pedro Cerdán y Víctor Beltrí, levantado cuando La Unión vivía el auge del plomo y la plata. Está sostenido por columnas de hierro y casi todos sus huecos son de cristal para dar luz al interior diáfano. Es BIC desde 1975 y sede del Festival Internacional del Cante de las Minas.","ver_alli":["Fachada del reloj con cupulín y campana","Estructura de columnas de hierro","Pináculos en flor de lis sobre las cornisas"],"visita":"exterior libre; interior en actos y en el festival (agosto)","fuentes":["https://es.wikipedia.org/wiki/Mercado_p%C3%BAblico_de_La_Uni%C3%B3n","https://www.wikidata.org/wiki/Q6010667"]},"t:museo-minero-de-la-union-la-union":{"municipio":"La Unión","posicion_nota":"Ubicación sin confirmar: está en el pueblo de La Unión; el punto no marca el sitio exacto.","lat_pueblo":37.6191,"lon_pueblo":-0.8755,"resumen":"Museo abierto en 2023 junto al antiguo Liceo de Obreros (1905), con más de 300 objetos de minería y metalurgia y unos 200 minerales, sobre todo de la Sierra Minera de Cartagena-La Unión. Incluye una recreación de mina en el sótano y conserva el último malacate de la sierra, la máquina para subir mineral y agua por los pozos.","ver_alli":["Malacate, último de la Sierra Minera","Colección de minerales","Recreación subterránea de mina"],"visita":"martes a viernes 9:30-13 h, sábado y domingo 10-13:30 h (horarios contradictorios en la web oficial); tel. 968 54 16 14","fuentes":["https://www.turismoregiondemurcia.es/en/museum/museo-minero-36/","https://m.murciatoday.com/the-mining-museum-of-la-union-opens-this-month-after-15-years-of-delays_2011033-a.html"]},"t:iglesia-de-nuestra-senora-del-rosario-la-union-la-union":{"municipio":"La Unión","posicion_nota":"Ubicación sin confirmar: está en el pueblo de La Unión; el punto no marca el sitio exacto.","lat_pueblo":37.6191,"lon_pueblo":-0.8755,"resumen":"Iglesia parroquial levantada entre 1894 y 1902 por el arquitecto Justo Millán, en sustitución de la ermita vieja de Herrerías. Lo más llamativo es la cúpula de tejas azules sobre la torre campanario. Dentro guarda imágenes de la Semana Santa Minera, como el Cristo de los Mineros (Jeriqué, 1913). Es BIC desde 2013.","ver_alli":["Cúpula de teja azul","Cristo de los Mineros (1913)","Virgen del Rosario, patrona"],"visita":"horario de culto","fuentes":["https://spanishnewstoday.com/the-iglesia-nuestra-señora-del-rosario-in-la-unión_24080-a.html","https://es.wikipedia.org/wiki/La_Uni%C3%B3n_(Espa%C3%B1a)"]},"t:parque-minero-de-la-union-y-mina-agrupa-vicenta-la-union":{"municipio":"La Unión","resumen":"Mina de la Sierra Minera explotada entre 1869 y 1957 y adaptada para visitas: una galería lleva a una gran cámara de unos 4.000 m² bajo el monte Sancti Spiritu, a unos 80 m de profundidad. Un tren sube por el Camino del 33 entre restos restaurados de lavaderos y fundiciones hasta la boca de la mina.","ver_alli":["Lago interior de agua anaranjada","Gran cámara subterránea","Camino del 33 con instalaciones mineras"],"visita":"visita guiada con reserva (tel. 968 00 21 40 / Oficina de Turismo 968 54 16 14); estuvo cerrado en 2022, comprobar","fuentes":["https://es.wikipedia.org/wiki/Mina_Agrupa_Vicenta","https://murciatoday.com/parque-minero-la-unión_6819-a.html","https://nominatim.openstreetmap.org"]},"t:museo-arqueologico-de-portman-la-union":{"municipio":"La Unión","resumen":"Pequeño museo municipal instalado en el antiguo Hospital de Caridad de Portmán, construido en 1892 para atender a los heridos de las minas. Sus tres salas muestran la minería de la sierra desde la Prehistoria, sobre todo la romana, cuando el puerto se llamaba Portus Magnus. Guarda fragmentos del gran mosaico polícromo de la villa del Paturro.","ver_alli":["Mosaico de la villa romana del Paturro","Útiles mineros romanos","Edificio del Hospital de Caridad (1892)"],"visita":"desconocido","fuentes":["https://es.wikipedia.org/wiki/Museo_Arqueol%C3%B3gico_de_La_Uni%C3%B3n","https://www.wikidata.org/wiki/Q6033142"]},"t:villa-romana-del-paturro-la-union":{"municipio":"La Unión","resumen":"Gran villa romana en terrazas cerca de Portmán, descubierta en 1969, con una zona de vivienda lujosa y otra industrial. Primero estuvo ligada a las minas de plata y plomo de Carthago Nova y desde los siglos I-II d. C. a la fabricación de garum; se abandonó en el siglo III. De aquí salió el mosaico polícromo más grande de la Región de Murcia.","ver_alli":["Terrazas de la villa con vistas a la bahía","Zona de vivienda y zona industrial"],"visita":"desconocido","fuentes":["https://es.wikipedia.org/wiki/Villa_romana_del_Paturro","https://www.wikidata.org/wiki/Q5474005"]},"t:casa-del-tio-lobo-portman-la-union":{"municipio":"La Unión","resumen":"Casa modernista de Víctor Beltrí, reconstruida en 1913 para el empresario minero Miguel Zapata Sáez, «el Tío Lobo», que murió en ella en 1918. Está en mal estado, aunque conserva las fachadas y algunas estancias.","ver_alli":["Fachada con la decoración de Beltrí"],"visita":"exterior libre","fuentes":["https://murciatoday.com/la-casa-del-t%C3%ADo-lobo-in-portm%C3%A1n_24100-a.html","https://www.wikidata.org/wiki/Q138515287","https://nominatim.openstreetmap.org"]},"t:museo-etnologico-de-roche-la-union":{"municipio":"La Unión","resumen":"Museo de la vida cotidiana en la pedanía de Roche, con objetos de los antiguos vecinos de la comarca minera y agrícola.","ver_alli":["Iluminación doméstica, pesas y medidas","Cerámica, vidrio y ropa","Aperos y objetos de esparto"],"visita":"con cita previa en la Oficina de Turismo (tel. 968 54 16 14); entrada 3 €","fuentes":["https://www.turismoregiondemurcia.es/en/museum/museo-etnologico-de-roche-100","https://www.wikidata.org/wiki/Q125904833"]},"t:iglesia-de-san-francisco-javier-y-museo-parroquial-san-javier":{"municipio":"San Javier","resumen":"Parroquia desde 1698, nacida de una ermita en torno a la cual se formó el pueblo; la iglesia actual se empezó en 1699 y se terminó con la torre en 1787. Ardió en la Guerra Civil y se perdieron sus Salzillos, pero los vecinos salvaron un Cristo crucificado de hacia 1600. Desde 1998 alberga un pequeño museo parroquial.","ver_alli":["Cristo crucificado anónimo de finales del XVI o comienzos del XVII","Museo con ornamentos bordados del siglo XVII y una cruz del XVI","Vista de la nave desde lo alto de la escalera del museo"],"visita":"iglesia en horario de culto; museo martes a sábado 10:30-13:30, gratuito (tel. 968 571 085)","fuentes":["https://murciatoday.com/museo-parroquial-san-javier_4869-a.html","https://es.wikipedia.org/wiki/San_Javier_(España)","https://www.wikidata.org/wiki/Q24939653"]},"t:museo-de-san-javier-historia-local-y-belen-de-espana-san-javier":{"municipio":"San Javier","resumen":"Museo municipal abierto en 1996 en la antigua casa cuartel de la Guardia Civil. Cuenta la vida del municipio entre mediados del siglo XIX y mediados del XX: la huerta, la pesca tradicional del Mar Menor y la Academia General del Aire. Tiene una sala dedicada al Belén de España, el gran belén que se monta en la plaza cada Navidad desde 1969.","ver_alli":["Sala etnográfica de agricultura y pesca","Sala del Belén de España","Recuerdos de la Academia General del Aire"],"visita":"gratuito; martes a viernes 9:30-13:30 y tardes (18-20:30 en verano, 16-18:30 en invierno), sábados 9:30-13:30; tel. 968 573 700 ext. 5105","fuentes":["https://www.turismoregiondemurcia.es/en/museum/museo-de-historia-local-de-san-javier-47/","https://www.wikidata.org/wiki/Q125904786"]},"t:chalet-barnuevo-san-javier":{"municipio":"San Javier","resumen":"Casa modernista de principios del siglo XX en el paseo de Santiago de la Ribera, levantada por la familia Barnuevo-Sandoval, que con ella y la ermita de Santiago dio origen a la localidad veraniega. Funcionó como hotel y residencia de verano. Tiene planta pentagonal y es Bien de Interés Cultural desde 1992.","ver_alli":["Mirador de madera artesonado","Cancela y fuente redonda a la entrada del jardín"],"visita":"exterior libre","fuentes":["https://es.wikipedia.org/wiki/Chalet_Barnuevo","https://www.wikidata.org/wiki/Q43129101"]},"t:museo-aeronautico-tiflologico-san-javier":{"municipio":"San Javier","resumen":"Museo al aire libre en el paseo Colón de Santiago de la Ribera, abierto en 2020 y pensado para personas con discapacidad visual o auditiva, con maquetas que se pueden tocar, braille y audioguía. Repasa los aviones ligados a la base aeronaval y a la Academia General del Aire.","ver_alli":["Réplica del hidroavión Dornier Wal de la época de la base aeronaval","Maquetas del T-34 Mentor, Saeta y C-101 de la Patrulla Águila"],"visita":"acceso libre","fuentes":["https://es.wikipedia.org/wiki/Museo_Aeronáutico_Tiflológico","https://www.wikidata.org/wiki/Q107313863"]},"t:hacienda-y-ermita-de-roda-san-javier":{"municipio":"San Javier","resumen":"Antigua hacienda agrícola cuyo edificio principal se construyó entre 1610 y 1620 sobre otro del siglo XV, y que dio origen al caserío de Roda. Tiene portada del siglo XVIII en forma de retablo, patio, casona con torre y jardines. La ermita, del siglo XVIII y atribuida a Jaime Bort (autor de la fachada de la catedral de Murcia), se comunica con la casa.","ver_alli":["Portada del XVIII en forma de retablo","Casona con torre","Ermita con dos pinturas de Mariano Ballester"],"visita":"exterior libre","fuentes":["https://www.turismoregiondemurcia.es/en/interesting_place/roda:-hacienda,-ermita-y-campo-de-golf-5121","https://es.wikipedia.org/wiki/San_Javier_(España)","https://www.openstreetmap.org/"]},"t:ermita-de-san-blas-san-javier":{"municipio":"San Javier","resumen":"Ermita de Santiago de la Ribera, destino de la romería de San Blas cada 3 de febrero, fiesta de interés turístico regional.","visita":"exterior libre","fuentes":["https://es.wikipedia.org/wiki/San_Javier_(España)","https://www.openstreetmap.org/"]},"t:iglesia-de-san-pedro-apostol-san-pedro-del-pinatar":{"municipio":"San Pedro del Pinatar","resumen":"Iglesia nacida de una ermita franciscana del siglo XVII, de cruz latina con tres naves y torre de cuatro cuerpos. Estuvo decorada con pinturas de la escuela de Nicolás de Villacis, de las que se han encontrado restos. Tuvo un San Pedro de Francisco Salzillo, destruido en 1936 junto con otras tres obras suyas.","ver_alli":["Torre de cuatro cuerpos con campanario","Restos de pintura mural del siglo XVII"],"visita":"horario de culto","fuentes":["https://es.wikipedia.org/wiki/Iglesia_de_San_Pedro_Apóstol_(San_Pedro_del_Pinatar)","https://es.wikipedia.org/wiki/San_Pedro_del_Pinatar","https://www.openstreetmap.org/"]},"t:casa-del-reloj-quinta-de-san-sebastian-san-pedro-del-pinatar":{"municipio":"San Pedro del Pinatar","resumen":"Villa de recreo modernista construida entre 1888 y 1895 por el arquitecto Pedro Cerdán para la familia Servet-Spottorno. Aquí murió en 1899 Emilio Castelar, último presidente de la Primera República. Mezcla tejados de aire alpino, maderas de gusto gótico y ladrillo mudéjar, y es Bien de Interés Cultural desde 1995. Hoy es restaurante.","ver_alli":["Reloj de la fachada que le da nombre","Escalera sobre columnas de madera y sala de billar pintada de verde","Jardín con palmeras y eucaliptos"],"visita":"exterior libre (interior como restaurante)","fuentes":["https://es.wikipedia.org/wiki/Quinta_de_San_Sebastián","https://www.wikidata.org/wiki/Q6095065"]},"t:palacio-del-baron-de-benifayo-museo-arqueologico-y-etnografico-san-pedro-del-pinatar":{"municipio":"San Pedro del Pinatar","resumen":"Palacete neomudéjar con dos torres almenadas terminado en 1892 para el barón de Benifayó, copia del pabellón de España de Lorenzo Álvarez Capra en la Exposición Universal de Viena de 1873. También se llama Casa de la Rusa, por una señora rusa que vivió en él. Hoy alberga el museo municipal, con arqueología submarina, fósiles y etnografía.","ver_alli":["Fachada neomudéjar con torres almenadas","Sala de arqueología submarina","Parque contiguo, antiguos jardines del palacio"],"visita":"horario de museo (desconocido)","fuentes":["https://es.wikipedia.org/wiki/Palacio_del_Barón_de_Benifayó","https://es.wikipedia.org/wiki/San_Pedro_del_Pinatar","https://www.wikidata.org/wiki/Q125904841"]},"t:museo-del-mar-san-pedro-del-pinatar":{"municipio":"San Pedro del Pinatar","resumen":"Pequeña colección de objetos marinos y marineros en el edificio Hogar del Pescador.","visita":"desconocido","fuentes":["https://es.wikipedia.org/wiki/San_Pedro_del_Pinatar","https://www.openstreetmap.org/"]},"t:lonja-de-pescado-de-lo-pagan-san-pedro-del-pinatar":{"municipio":"San Pedro del Pinatar","resumen":"Lonja del puerto de Lo Pagán donde puede verse la subasta de pescado al estilo tradicional.","visita":"desconocido","fuentes":["https://es.wikipedia.org/wiki/San_Pedro_del_Pinatar","https://www.openstreetmap.org/"]},"t:torre-del-rame-los-alcazares":{"municipio":"Los Alcázares","resumen":"Torre vigía de finales del siglo XVI levantada por Diego Bienvengud Rosique, capitán y regidor de Cartagena, para proteger sus fincas de los ataques de piratas berberiscos. Formaba parte de la red de torres que vigilaba el Mar Menor y se cree que se alza sobre una torre árabe citada en el siglo XIII. Está en el antiguo límite entre los concejos de Cartagena y Murcia.","ver_alli":["Torre de aspecto de fortaleza en mitad del campo","Paisaje agrícola del Campo de Cartagena alrededor"],"visita":"exterior libre","fuentes":["https://www.turismoregiondemurcia.es/en/monument/torre-del-rame-384/","https://turismo.losalcazares.es/wp-content/uploads/2023/06/Folleto-Rutas-Turisticas-2023.pdf","https://www.wikidata.org/wiki/Q43120341"]},"t:museo-aeronautico-municipal-los-alcazares":{"municipio":"Los Alcázares","resumen":"Pequeño museo abierto en 1999 en un edificio de los años 30 construido como refugio para pobres y viajeros. Cuenta la historia de la aviación en Los Alcázares, donde en 1915 se creó la primera base de hidroaviones de España. Expone maquetas de los aviones que volaron aquí, fotografías, planos, uniformes y hélices.","ver_alli":["Maquetas de los primeros hidroaviones de la base","Colección fotográfica de la aviación y del pueblo","Hélices, uniformes y documentos"],"visita":"entre semana 9-14 (verano 10-13); grupos con cita en turismo; tel. 968 582 107 (Av. de la Libertad 37)","fuentes":["https://murciatoday.com/the-municipal-aeronautics-museum-of-los-alcazares_1000189690-a.html","https://es.wikipedia.org/wiki/Los_Alcázares","https://www.openstreetmap.org/"]},"t:aerodromo-historico-de-los-alcazares-los-alcazares":{"municipio":"Los Alcázares","resumen":"Primera base de hidroaviones de España, creada en 1915 y todavía en uso militar. Fue uno de los grandes aeródromos de la aeronáutica militar en la primera mitad del siglo XX y por ella pasaron pioneros como el infante Alfonso de Orleans. Desde 2022 se expone un C-101 que voló con la Patrulla Águila.","ver_alli":["Avión C-101 de la Patrulla Águila expuesto","Edificios históricos de la base aérea"],"visita":"ruta guiada de la Base Aérea con reserva en turismo","fuentes":["https://turismo.losalcazares.es/wp-content/uploads/2023/06/Folleto-Rutas-Turisticas-2023.pdf","https://es.wikipedia.org/wiki/Los_Alcázares","https://www.wikidata.org/wiki/Q125904745"]},"t:iglesia-de-nuestra-senora-de-la-asuncion-los-alcazares":{"municipio":"Los Alcázares","resumen":"Parroquia levantada entre 1898 y 1905 donde en 1890 había un pequeño oratorio, en los años en que nacía el veraneo en Los Alcázares.","visita":"horario de culto","fuentes":["https://turismo.losalcazares.es/wp-content/uploads/2023/06/Folleto-Rutas-Turisticas-2023.pdf","https://www.openstreetmap.org/"]},"t:aljibe-colorao-los-alcazares":{"municipio":"Los Alcázares","resumen":"Antiguo aljibe, ejemplo de los once que llegó a tener la zona cuando pertenecía al Concejo de Murcia.","visita":"exterior libre","fuentes":["https://turismo.losalcazares.es/wp-content/uploads/2023/06/Folleto-Rutas-Turisticas-2023.pdf","https://www.openstreetmap.org/"]},"t:museo-de-arte-urbano-los-alcazares":{"municipio":"Los Alcázares","posicion_nota":"Ubicación sin confirmar: está en el pueblo de Los Alcázares; el punto no marca el sitio exacto.","lat_pueblo":37.7436,"lon_pueblo":-0.8497,"resumen":"Museo al aire libre de más de 150 murales de más de 80 artistas repartidos por las calles del municipio.","visita":"acceso libre","fuentes":["https://turismo.losalcazares.es/wp-content/uploads/2023/06/Folleto-Rutas-Turisticas-2023.pdf"]},"t:casas-cueva-del-barrio-primero-de-mayo-san-miguel-de-salinas":{"municipio":"San Miguel de Salinas","posicion_nota":"Ubicación sin confirmar: está en el pueblo de San Miguel de Salinas; el punto no marca el sitio exacto.","lat_pueblo":37.9806,"lon_pueblo":-0.7897,"resumen":"Conjunto de viviendas excavadas en la ladera a finales del siglo XVIII y principios del XIX, en el barrio Primero de Mayo y la calle Zenia. Son un ejemplo del hábitat troglodita que se extendió por la Vega Baja.","ver_alli":["Fachadas encaladas de las cuevas","Calle Zenia"],"visita":"exterior libre","fuentes":["https://www.comunitatvalenciana.com/es/alacant-alicante/san-miguel-de-salinas"]},"t:molino-de-la-tia-pela-san-miguel-de-salinas":{"municipio":"San Miguel de Salinas","posicion_nota":"Ubicación sin confirmar: está fuera del pueblo, en el término de San Miguel de Salinas; el punto no marca el sitio.","lat_pueblo":37.9806,"lon_pueblo":-0.7897,"resumen":"Restos de un antiguo molino de viento del que solo quedan las piedras de moler.","visita":"exterior libre","fuentes":["https://www.comunitatvalenciana.com/es/alacant-alicante/san-miguel-de-salinas"]},"t:hacienda-la-torre-roldan-torre-pacheco":{"municipio":"Torre-Pacheco","posicion_nota":"Ubicación sin confirmar: está fuera del pueblo, en el término de Torre-Pacheco; el punto no marca el sitio.","lat_pueblo":37.7431,"lon_pueblo":-0.9539,"resumen":"Hacienda con referencias desde 1680 que perteneció a la familia genovesa Ferro. Conserva un reloj de sol de 1754, una veleta con las iniciales F.S. y una torre con campana.","ver_alli":["Reloj de sol de 1754","Veleta con iniciales F.S.","Torre con campana"],"visita":"desconocido","fuentes":["https://www.turismoregiondemurcia.es/catalogos/OTTPACHECO34052581Guia Turistica.pdf"]},"t:balnearios-de-madera-de-santiago-de-la-ribera-san-javier":{"municipio":"San Javier","posicion_nota":"Ubicación sin confirmar: está fuera del pueblo, en el término de San Javier; el punto no marca el sitio.","lat_pueblo":37.8037,"lon_pueblo":-0.8343,"resumen":"Pasarelas de madera que se adentran en el Mar Menor desde las playas de Santiago de la Ribera, nacidas a comienzos del siglo XX para facilitar el baño. En sus plataformas del fondo tienen casetas que servían de vestuarios. Son una imagen típica de la costa del Mar Menor.","ver_alli":["Pasarelas sobre el agua con casetas al final","Paseo Colón con casonas de veraneo de principios del siglo XX"],"visita":"acceso libre (algunos son privados)","fuentes":["https://es.wikipedia.org/wiki/San_Javier_(España)","https://murciatoday.com/traditional-bathing-station-restored-in-santiago-de-la-ribera_1000269433-a.html"]},"t:molino-de-quintin-san-pedro-del-pinatar":{"municipio":"San Pedro del Pinatar","posicion_nota":"Ubicación sin confirmar: está fuera del pueblo, en el término de San Pedro del Pinatar; el punto no marca el sitio.","lat_pueblo":37.8363,"lon_pueblo":-0.7886,"resumen":"Molino de viento de planta cónica en Lo Pagán, junto a la explanada de las salinas, usado para mover agua y referencia para llegar a los baños de lodo.","visita":"exterior libre","fuentes":["https://m.murciatoday.com/molino-de-quintín-san-pedro-del-pinatar_9770-a.html"]},"t:molino-del-tio-manuel-lambertos-los-alcazares":{"municipio":"Los Alcázares","posicion_nota":"Ubicación sin confirmar: está fuera del pueblo, en el término de Los Alcázares; el punto no marca el sitio.","lat_pueblo":37.7436,"lon_pueblo":-0.8497,"resumen":"Molino de dos torres con pozo de noria de tiro, testimonio del campo tradicional.","visita":"exterior libre","fuentes":["https://turismo.losalcazares.es/wp-content/uploads/2023/06/Folleto-Rutas-Turisticas-2023.pdf"]}});